def depthwise_conv(x: Tensor4D, w: Tensor4D, kernel_size: Int32) -> Tensor4D {
let (batch, in_channels, height, width) = x.shape;
let (out_channels, _, _, _) = w.shape;
assert(in_channels == out_channels); // 深度卷积通道数一致
let y: Tensor4D = zeros((batch, out_channels, height, width));
