深度卷积将输入通道与输出通道一一对应，组内卷积独立计算，TileLang通过@group注解指定通道分组，优化组内数据复用。实现步骤：1. 定义输入（多通道）、深度卷积核（单通道输入、单通道输出）；2. 用@group按通道分组（每组1个输入通道、1个输出通道）；3. 编写组内卷积逻辑，TileLang自动优化组内数据的共享内存存储。核心代码：
// TileLang代码
@tile
def depthwise_conv(x: Tensor4D, w: Tensor4D, kernel_size: Int32) -> Tensor4D {
let (batch, in_channels, height, width) = x.shape;
let (out_channels, _, _, _) = w.shape;
assert(in_channels == out_channels); // 深度卷积通道数一致
let y: Tensor4D = zeros((batch, out_channels, height, width));
// 按通道分组，每组1个输入+1个输出通道
@group(dim=1, size=1)
for c in 0..in_channels-1 {
@tile(size=16, dim=2)
for row in 0..height-1 {
@tile(size=16, dim=3)
for col in 0..width-1 {
let y_val: Float32 = 0.0;
for k in 0..kernel_size-1 {
for l in 0..kernel_size-1 {
let x_row = row + k - kernel_size//2;
let x_col = col + l - kernel_size//2;
let x_val = x.data[batch][c][x_row][x_col] if (x_row >=0 && x_row =0 && x_col < width) else 0.0;
let w_val = w.data[c][0][k][l];
y_val += x_val * w_val;
}
}
y.data[batch][c][row][col] = y_val;
}
}
}
return y;
}
TileLang的通道分组优化让组内数据集中存储，减少共享内存访问冲突，提升组内数据复用率，深度卷积性能比普通卷积提升2-3倍，适合移动设备和边缘计算场景。

