let x_col = col + l - kernel_size//2;
let x_val = x.data[batch][c][x_row][x_col] if (x_row >=0 && x_row =0 && x_col < width) else 0.0;
let w_val = w.data[c][0][k][l];
y_val += x_val * w_val;
}
}
y.data[batch][c][row][col] = y_val;
}
}
}
return y;
}
