int row = blockIdx.x * blockDim.x + threadIdx.x;
if (row < n) {
for (int i = 0; i < max_nnz; i++) {
int idx = csrRowPtr[row] + i;
if (idx < csrRowPtr[row+1]) {
ell_col_ind[row * max_nnz + i] = csrColInd[idx];
ell_val[row * max_nnz + i] = csrVal[idx];
