__global__ void tensorCoreExample(float *A, float *B, float *C, int N) {
    wmma::fragment fragA;
    wmma::fragment fragB;
    wmma::fragment fragC;

    wmma::load_matrix_sync(fragA, A, N);
    wmma::load_matrix_sync(fragB, B, N);
