#define TILE_WIDTH 32
__global__ void matrixMulSharedMem(float *A, float *B, float *C, int width) {
    __shared__ float As[TILE_WIDTH][TILE_WIDTH];
    __shared__ float Bs[TILE_WIDTH][TILE_WIDTH];
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = blockIdx.y * TILE_WIDTH + ty;
    int col = blockIdx.x * TILE_WIDTH + tx;
    float value = 0.0;
    for (int m = 0; m < width / TILE_WIDTH; ++m) {
        As[ty][tx] = A[row * width + (m * TILE_WIDTH + tx)];
        Bs[ty][tx] = B[(m * TILE_WIDTH + ty) * width + col];
        __syncthreads();
        for (int k = 0; k < TILE_WIDTH; ++k) {
            value += As[ty][k] * Bs[k][tx];
        }
        __syncthreads();
    }
    if (row < width && col < width) {
        C[row * width + col] = value;
    }
}

该代码通过共享内存缓存A和B矩阵的tile，避免了每次计算都从全局内存中加载数据，减少了内存访问延迟，从而提高了矩阵乘法的执行效率。

Triton利用PyTorch的自动微分框架（torch.autograd.Function）与内存复用技术相结合，大幅提升了卷积神经网络（ConvNets）反向传播的计算性能。首先，Triton通过定义高效的前向卷积内核，减少了冗余计算。在反向传播中，Triton复用了前向计算中的输入和权重分块缓存，从而避免了重复加载数据，极大地降低了内存访问开销。核心代码片段如下所示：
