float variance = (idx (variance);
if (tid == 0) s_variance = rsqrtf(variance / (float) K + epsilon);
__syncthreads();
reg_y.x = reg_x.x * s_variance * g;
reg_y.y = reg_x.y * s_variance * g;
reg_y.z = reg_x.z * s_variance * g;
