void ScanThenFan(const int32_t* input, int32_t* buffer, int32_t* output,
                 size_t n) {
  size_t part_size = 1024;  // Tuned
  size_t part_num = (n + part_size - 1) / part_size;
  size_t block_num = std::min(part_num, 128);
  int32_t* part = buffer;
  ScanAndWritePartSumKernel>>(input, part, output, n, part_num);
  ScanPartSumKernel>>(part, part_num);
  AddBaseSumKernel>>(part, output, n, part_num);
}

