#define TILE_WIDTH 16

__global__ void convolution_optimized(float *input, float *output, float *kernel, int width, int height, int kernel_size) {
    __shared__ float shared_input[TILE_WIDTH + kernel_size - 1][TILE_WIDTH + kernel_size - 1];
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = blockIdx.y * TILE_WIDTH + ty;
    int col = blockIdx.x * TILE_WIDTH + tx;

    // 加载输入数据到共享内存
    for (int i = 0; i < kernel_size; ++i) {
        for (int j = 0; j < kernel_size; ++j) {
            if (row + i < height && col + j < width) {
                shared_input[ty + i][tx + j] = input[(row + i) * width + (col + j)];
            }
        }
    }
    __syncthreads();

