    for (int i = 0; i < kernel_size; ++i) {
        for (int j = 0; j < kernel_size; ++j) {
            if (row + i < height && col + j < width) {
                value += shared_input[ty + i][tx + j] * kernel[i * kernel_size + j];
            }
        }
    }

    if (row < height && col < width) {
        output[row * width + col] = value;
    }
}


