__global__ void convolution_kernel(float* d_input, float* d_output, float* d_kernel, int width, int height, int kernel_size) {
    __shared__ float shared_kernel[BLOCK_SIZE][BLOCK_SIZE];
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = blockIdx.y * BLOCK_SIZE + ty;
    int col = blockIdx.x * BLOCK_SIZE + tx;

    if (ty < kernel_size && tx < kernel_size) {
        shared_kernel[ty][tx] = d_kernel[ty * kernel_size + tx];
    }
    __syncthreads();

    if (row < height && col < width) {
        float result = 0.0f;
        for (int i = 0; i < kernel_size; i++) {
            for (int j = 0; j < kernel_size; j++) {
                result += d_input[(row + i) * width + (col + j)] * shared_kernel[i][j];
            }
        }
        d_output[row * width + col] = result;
    }
}

在CUDA卷积算子中，零填充（Zero Padding）是通过在计算输入索引时判断该索引是否超出输入边界来实现的。如果超出边界，则将输入值视为零，避免访问非法内存。例如，当行或列超出矩阵边界时，使用条件语句判断是否需要填充为零。具体的代码实现如下：


