type Tensor2D = { 
    data: [T], 
    width: Int32, 
    height: Int32, 
    pitch: Int32 
} 

@tile
def conv2d_tiled(x: Tensor2D, w: Tensor2D, mask_size: Int32) -> Tensor2D { 
    let halo = (mask_size - 1) // 2; 
    let tile_size = 16; 
    // 输出分块，每个块带halo细胞
    @tile(size=tile_size, halo=(halo, halo)) 
    for row in 0..x.height-1 { 
        @tile(size=tile_size, halo=(halo, halo)) 
        for col in 0..x.width-1 { 
            let y_val: Float32 = 0.0; 
            for k in 0..mask_size-1 { 
                for l in 0..mask_size-1 { 
                    // 自动访问halo细胞，无需手动判断边界 
                    let x_val = x.data[(row + k - halo) * x.pitch + (col + l - halo)]; 
                    let w_val = w.data[k * mask_size + l]; 
                    y_val += x_val * w_val; 
                } 
            } 
            // 存储输出块核心细胞 
            output.data[row * output.pitch + col] = y_val; 
        } 
    } 
    return output; 
} 


通过这种方式，TileLang自动加载halo细胞并处理边界条件，同时优化了内存访问，极大地简化了tiled卷积的实现过程。

TileLang通过`@transpose`注解自动优化转置矩阵的访问模式，结合分块策略提升并行度。在优化稀疏矩阵转置后的SpMV（稀疏矩阵-向量乘法）算子时，可以使用TileLang的以下步骤：首先，定义转置后的稀疏矩阵（例如，CSC格式）；然后，使用`@tile`注解进行按列分块，确保转置后的矩阵能够利用连续的访问模式。接着，编写SpMV的计算逻辑，TileLang会自动优化线程映射和内存访问模式。例如，核心代码如下：

