}
__syncthreads();
if (tid == 0) {
  output[blockIdx.x] = s_data[0];
}

在CUDA中实现NMS（非极大值抑制）时，硬NMS的关键在于计算每一对框（Box）之间的IOU（交并比）。为提高性能，可以将计算分配到多个线程上，并充分利用共享内存来减少全局内存访问。硬NMS的流程一般是：先根据得分对框进行排序，然后逐个框与剩余框计算IOU，若IOU超过阈值，则合并框。对于IOU的计算，我们可以在CUDA中使用线程块内并行处理。每个线程计算一个框对的IOU，同时避免重复计算。代码示例如下：


__device__ float iou_of(Box a, Box b) {
  float inner_x1 = fmaxf(a.x1, b.x1);
  float inner_y1 = fmaxf(a.y1, b.y1);
  float inner_x2 = fminf(a.x2, b.x2);
  float inner_y2 = fminf(a.y2, b.y2);
  float inner_w = fmaxf(0.0f, inner_x2 - inner_x1);
  float inner_h = fmaxf(0.0f, inner_y2 - inner_y1);
  float inner_area = inner_w * inner_h;
  float area_a = (a.x2 - a.x1) * (a.y2 - a.y1);
  float area_b = (b.x2 - b.x1) * (b.y2 - b.y1);
  return inner_area / (area_a + area_b - inner_area);
}

