    __shared__ float Bs[TILE][TILE + 1]; // padding消冲突

    int tid = threadIdx.x;
    int tx = tid / 8;
    int ty = tid % 8;

    As[tx][ty] = A[tx * TILE + ty];
    Bs[tx][ty] = B[tx * TILE + ty];
    __syncthreads();

    float acc = 0.f;
    for (int k = 0; k < TILE; ++k) {
        acc += As[tx][k] * Bs[k][ty];
    }
    C[tx * TILE + ty] = acc;
}

在实际Profiling中，对比这两个kernel可以清晰看到无padding版本在SMEM访存阶段产生额外Wavefronts，而padding版本能够让Warp在更少的周期内完成共享内存访问，从而减少Stall MIO Throttle。是否值得做这种优化，最终仍以端到端kernel耗时为准，但从架构与Profiling指标角度看，这类冲突消除通常是高性价比的优化手段。

下面给出一个典型的CUDA矩阵转置实现，该实现使用32×32的tile，并通过在共享内存中引入列方向padding（等价于TILE_COL_SIZE=4的思想）来避免Bank Conflict。其核心思想是在共享内存中让相邻行的起始地址错开bank映射，从而保证warp内访问无冲突。

#include 

#define TILE_DIM 32
#define BLOCK_ROWS 8

__global__ void transposeNoBankConflict(const float* __restrict__ A,
                                        float* __restrict__ B,
                                        int M, int N) {
    __shared__ float tile[TILE_DIM][TILE_DIM + 1];

    int x = blockIdx.x * TILE_DIM + threadIdx.x;
    int y = blockIdx.y * TILE_DIM + threadIdx.y;

    if (x < N && y < M) {
        tile[threadIdx.y][threadIdx.x] = A[y * N + x];
    }

    __syncthreads();

    int transposed_x = blockIdx.y * TILE_DIM + threadIdx.x;
    int transposed_y = blockIdx.x * TILE_DIM + threadIdx.y;

    if (transposed_x < M && transposed_y < N) {
        B[transposed_y * M + transposed_x] = tile[threadIdx.x][threadIdx.y];
    }
}

在这个实现中，tile第二维被定义为TILE_DIM+1，这个额外的padding会打破共享内存中行与行之间的对齐关系，确保当线程按列访问tile[tx][ty]时，地址不会集中映射到同一个bank，从而彻底消除Bank Conflict。该Kernel在Nsight Compute中通常可以观察到接近理论最优的wavefronts数量和极低的shared memory stall，是矩阵转置中最经典且实践价值极高的优化范式。

在CUDA中，矩阵转置的朴素实现通过每个线程负责处理矩阵中的一个元素，首先将矩阵划分为多个子块（tile），每个tile与线程块的大小相同。在2D grid和block配置中，每个线程通过计算自己的索引（ix, iy）来映射到矩阵A中的元素，并将对应的元素存储到矩阵B中。具体来说，若矩阵A的元素A[r,c]对应转置矩阵B中的元素B[c,r]，那么线程负责的转置操作为B[ix * M + iy] = A[iy * N + ix]。在朴素实现中，我们根据线程的索引直接对矩阵元素进行读取和写入。代码实现如下：


__global__ void naiveTranspose(int *A, int *B, int N, int M) {
    int ix = blockIdx.x * blockDim.x + threadIdx.x;
    int iy = blockIdx.y * blockDim.y + threadIdx.y;
    if (ix < N && iy < M) {
        B[iy * N + ix] = A[ix * M + iy];
    }
}

CUDA中，每32个线程组成一个warp，warp是最小的执行单元，同一个warp中的32个线程会执行相同的指令。在矩阵转置的情况下，考虑到warp中的线程按行优先排序的特点，我们可以优化矩阵转置操作。在朴素实现中，block的同一行内的线程读取矩阵A中的连续元素，并将它们写入矩阵B中不连续的位置，这种方法称为NaiveRow。然而，这种方法可能导致内存访问不连续，影响性能。为了利用warp的优势，我们可以使用适当的内存访问模式，确保连续的线程访问连续的内存位置，以提高内存访问的效率。代码示例如下：


__global__ void optimizedTranspose(int *A, int *B, int N, int M) {
    __shared__ int tile[TILE_WIDTH][TILE_WIDTH + 1];
    int ix = blockIdx.x * blockDim.x + threadIdx.x;
    int iy = blockIdx.y * blockDim.y + threadIdx.y;
    if (ix < N && iy < M) {
        tile[threadIdx.y][threadIdx.x] = A[iy * N + ix];
    }
    __syncthreads();
    if (ix < N && iy < M) {
        B[ix * M + iy] = tile[threadIdx.x][threadIdx.y];
    }
}

为了避免不必要的全局内存访问，我们可以通过共享内存（__shared__）来存储每个线程块（block）内的矩阵数据。在矩阵转置操作中，首先将每个线程块中的数据加载到共享内存中，这样线程可以快速访问共享内存中的数据，而不必每次都从全局内存读取。这种方法减少了全局内存访问的开销，提高了计算效率。具体而言，可以通过tile（子矩阵）来进行局部存储，将块内元素存储到共享内存中，然后线程按照转置规则将结果写回全局内存。以下是使用共享内存优化矩阵转置的代码：


__global__ void optimizedTransposeSharedMem(int *A, int *B, int N, int M) {
    __shared__ int tile[TILE_WIDTH][TILE_WIDTH + 1];
    int ix = blockIdx.x * blockDim.x + threadIdx.x;
    int iy = blockIdx.y * blockDim.y + threadIdx.y;
    if (ix < N && iy < M) {
        tile[threadIdx.y][threadIdx.x] = A[iy * N + ix];
    }
    __syncthreads();
    if (ix < N && iy < M) {
        B[ix * M + iy] = tile[threadIdx.x][threadIdx.y];
    }
}

CUDA中的内存事务（memory transaction）会在执行时按照一定的粒度合并线程的内存访问请求。对于float类型的数据（每个数据4字节），常见的内存事务粒度为32、64或128字节。为了优化Naive转置算法的性能，关键是选择合适的block尺寸以充分利用内存事务的合并特性。在NaiveRow和NaiveCol的实现中，内存访问模式影响内存事务的合并情况，因此选择block尺寸时需要确保内存访问能够尽可能对齐。例如，在NaiveRow中，选择32×32或16×16的block尺寸可以使得32个线程访问的数据处于对齐状态，避免内存事务的浪费。具体而言，32×32的block可以确保每个warp内的线程在读取A矩阵时连续访问内存，这样32个线程访问128字节的内存（32个4字节数据），可以合并为4个memory transaction，利用率达到100%。类似的，NaiveCol实现中，合理选择block尺寸也有助于减少非对齐访问，提升带宽利用率。代码示例如下：

cpp
__global__ void transposeNaiveRow(float* A, float* B, const int M, const int N) {
    int ix = blockIdx.x * blockDim.x + threadIdx.x;
    int iy = blockIdx.y * blockDim.y + threadIdx.y;

    if (iy < M && ix < N) {
        B[ix * M + iy] = A[iy * N + ix];
    }
}

__global__ void transposeNaiveCol(float* A, float* B, const int M, const int N) {
    int ix = blockIdx.x * blockDim.x + threadIdx.x;
    int iy = blockIdx.y * blockDim.y + threadIdx.y;

    if (iy < N && ix < M) {
        B[iy * M + ix] = A[ix * N + iy];
    }
}

通过调整block尺寸，例如选择32×32或16×16，能够确保线程的内存访问对齐，从而提升内存带宽的利用率，减少内存事务的浪费，最终提高整体性能。

在计算能力8.9的平台上，global memory的transaction粒度为32字节，因此设计NaiveRow风格的矩阵逐元素算子时，核心目标是让warp内线程在x方向尽可能连续地访问内存。假设矩阵以行优先方式存储，每个元素为float类型，那么threadIdx.x应直接映射到矩阵的列索引，从而保证warp中线程访问的是连续的float元素。将block总线程数设为256可以在occupancy和调度开销之间取得良好平衡，而在二维划分上，选择如blockDim=(32,8)或(16,16)这样的配置，可以让warp在x方向拥有足够多的连续线程，显著减少memory transaction数量。以下是一个符合该设计思路的完整CUDA kernel示例：

