template
__global__ void transposeColNelements(float* A, float* B, const int M, const int N) {
    int r0 = blockIdx.x * Bm;
    int c0 = blockIdx.y * Bn;

    #pragma unroll
    for (int x = threadIdx.x; x = M) break;

        #pragma unroll
        for (int y = threadIdx.y; y = N) break;
            B[c * M + r] = A[r * N + c];
        }
    }
}

通过这样的实现，每个线程只访问自己负责的数据块，而不需要访问全局内存中的其他数据，从而减少了不必要的内存访问和带宽压力，最终提高了整体性能。

利用shared memory的核心思想是将全局内存中不利于合并访问的访存模式，转换为在shared memory中的重排操作。具体做法是：首先所有thread按行从输入矩阵中读取数据，这一步天然满足global memory的连续访问条件；随后将读取的数据按原始布局写入shared memory；接着thread再从shared memory中按列读取数据，但由于shared memory是片上存储，其访问延迟和带宽远高于global memory，且不存在memory transaction合并的限制；最后再由所有thread按行将数据写回输出矩阵。这样，global memory层面上的读和写都变成了按行访问，从而使每个warp的128字节访问稳定合并为4次memory transactions，显著提升带宽利用率。下面给出一个典型的CUDA矩阵转置实现示例，其中使用shared memory消除非合并访问：

cuda
#include 
#include 

#define TILE_DIM 32
#define BLOCK_ROWS 8

__global__ void transpose_shared(const float* __restrict__ A,
                                 float* __restrict__ B,
                                 int M, int N) {
    __shared__ float tile[TILE_DIM][TILE_DIM + 1];

    int x = blockIdx.x * TILE_DIM + threadIdx.x;
    int y = blockIdx.y * TILE_DIM + threadIdx.y;

    for (int j = 0; j < TILE_DIM; j += BLOCK_ROWS) {
        if (x < N && y + j < M) {
            tile[threadIdx.y + j][threadIdx.x] = A[(y + j) * N + x];
        }
    }

    __syncthreads();

    x = blockIdx.y * TILE_DIM + threadIdx.x;
    y = blockIdx.x * TILE_DIM + threadIdx.y;

    for (int j = 0; j < TILE_DIM; j += BLOCK_ROWS) {
        if (x < M && y + j < N) {
            B[(y + j) * M + x] = tile[threadIdx.x][threadIdx.y + j];
        }
    }
}


在这个实现中，通过在shared memory中引入一个额外的padding列，避免了bank conflict问题；同时BLOCK_ROWS控制了每个thread在y方向上处理的元素数量，保证了并行度和寄存器使用的平衡。这种写法已经成为CUDA矩阵转置算子的经典高性能实现范式，在实际应用中能够接近理论峰值带宽。

共享内存是CUDA中一个重要的优化资源，尤其是在矩阵乘法等运算中，合理使用共享内存能够显著减少全局内存访问带来的性能瓶颈。在矩阵乘法中，可以通过`tile`将矩阵分块，并将每个块加载到共享内存中。每个线程块负责一个矩阵子块的计算，每个线程在共享内存中存取多个矩阵元素，这样可以避免每次计算时都从全局内存读取数据。在代码中，首先根据线程块的索引计算出该块在矩阵中的位置，例如`r0 = blockIdx.y * Bm`和`c0 = blockIdx.x * Bn`，这确定了块的起始位置。随后，线程根据自己的`threadIdx`计算自己负责的矩阵元素位置，并将这些元素加载到共享内存。这样可以通过共享内存提供低延迟的数据访问，从而大大提高计算性能。以下是一个示例代码片段，展示了如何将矩阵A的元素按块加载到共享内存中：


