在CUDA中，高效实现矩阵转置的关键是使用共享内存和线程同步。共享内存提供了低延迟的内存访问，相比全局内存，它的访问速度更快，可以显著减少内存带宽的压力。在转置操作中，首先每个线程块将矩阵的一个小块（tile）加载到共享内存中，完成读取后，利用线程同步来确保数据正确传递到共享内存。然后，线程块将共享内存中的数据写回全局内存中的目标矩阵。在代码中，可以通过`__syncthreads()`来同步线程，确保每个线程都完成了对共享内存的访问。下面是完整的代码示例：

cuda
template
__global__ void transposeShared(float* A, float* B, const int M, const int N) {
    __shared__ float tile[Bm][Bn];

    int r0 = blockIdx.y * Bm;
    int c0 = blockIdx.x * Bn;

    for (int y = threadIdx.y; y = M) break;

        for (int x = threadIdx.x; x = N) break;

        for (int x = threadIdx.x; x < Bm; x += blockDim.x) {
            int r = r0 + x;
            if (r < M) {
                B[c * M + r] = tile[x][y];
            }
        }
    }
}

此实现采用了两次`for`循环：第一次用于将矩阵A的元素加载到共享内存中，第二次用于将共享内存中的元素写回到矩阵B中。通过这种方式，可以高效地完成矩阵转置操作。

要在CUDA中优化矩阵转置操作，特别是在处理大型矩阵时，最关键的是减少全局内存的访问和提高数据的局部性。可以通过使用共享内存来加载矩阵的子块（tile），并通过线程块进行协作，避免每个线程单独访问全局内存中的元素。此外，利用`__syncthreads()`进行线程同步，可以确保每个线程块在访问共享内存时不会发生冲突，从而保证数据的正确性。对于较大的矩阵，适当选择线程块和tile的大小也是优化的关键，可以根据硬件的特性进行调优。下面是一个优化后的CUDA代码示例，展示了如何利用共享内存和线程同步实现高效的矩阵转置：

cuda
template
__global__ void transposeShared(float* A, float* B, const int M, const int N) {
    __shared__ float tile[Bm][Bn];

    int r0 = blockIdx.y * Bm;
    int c0 = blockIdx.x * Bn;

    for (int y = threadIdx.y; y = M) break;

        for (int x = threadIdx.x; x = N) break;

        for (int x = threadIdx.x; x < Bm; x += blockDim.x) {
            int r = r0 + x;
            if (r < M) {
                B[c * M + r] = tile[x][y];
            }
        }
    }
}

通过这种方式，线程块的协作和共享内存的使用大大减少了对全局内存的频繁访问，提高了整体性能。

在CUDA中实现矩阵乘法时，可以使用共享内存来减少对全局内存的频繁访问，提升性能。首先，将输入矩阵分割成多个tile，每个tile会加载到共享内存中，这样每个线程块可以共享这些数据，减少对全局内存的访问频率。以下是一个优化后的矩阵乘法的CUDA代码示例，使用共享内存来存储tile并进行计算：

cpp
#define TILE_WIDTH 16

__global__ void matrixMulSharedMemory(float* A, float* B, float* C, int M, int N, int K) {
    __shared__ float tileA[TILE_WIDTH][TILE_WIDTH];
    __shared__ float tileB[TILE_WIDTH][TILE_WIDTH];
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = blockIdx.y * TILE_WIDTH + ty;
    int col = blockIdx.x * TILE_WIDTH + tx;

    float value = 0;
    for (int t = 0; t < (N + TILE_WIDTH - 1) / TILE_WIDTH; t++) {
        if (row < M && t * TILE_WIDTH + tx < N)
            tileA[ty][tx] = A[row * N + t * TILE_WIDTH + tx];
        else
            tileA[ty][tx] = 0.0;

        if (col < K && t * TILE_WIDTH + ty < N)
            tileB[ty][tx] = B[(t * TILE_WIDTH + ty) * K + col];
        else
            tileB[ty][tx] = 0.0;

        __syncthreads();

        for (int k = 0; k < TILE_WIDTH; k++)
            value += tileA[ty][k] * tileB[k][tx];

        __syncthreads();
    }

    if (row < M && col < K)
        C[row * K + col] = value;
}


该代码通过共享内存将每个tile的矩阵块加载到共享内存中，每个线程块内的线程共同计算该tile的矩阵乘积。通过这种方式，每个线程块中的线程会反复访问共享内存中的数据，而不是频繁访问全局内存，从而显著提高性能。

在CUDA编程中，swizzling机制通过调整共享内存中元素的物理存储位置来避免bank conflict。具体来说，逻辑行和逻辑列的坐标通过映射函数进行转换，物理行和逻辑行一致，而物理列则由逻辑行和逻辑列的异或运算得出：`cp = cl ^ rl`。这一机制确保了每个元素被分配到不同的bank，从而避免了多个线程访问同一bank的问题。代码实现中，数据读取和写入时需要进行坐标调整：读取阶段修改为`tile[y][x ^ y] = A[r0 + y, c0 + x]`，写入阶段修改为`tile[x][x ^ y]`。这种方式优化了内存访问模式，提高了并行效率。以下是完整代码：
cpp
template
__global__ void transposeSharedSwizzling(float* A, float* B, const int M, const int N) {
  __shared__ float tile[Bm][Bn];

  /* -------- 读取阶段 -------- */
  int r0 = blockIdx.y * Bm;
  int c0 = blockIdx.x * Bn;
  int y = threadIdx.y;
  int x = threadIdx.x;
  tile[y][x ^ y] = A[r0 + y, c0 + x];

  /* -------- 写入阶段 -------- */
  __syncthreads();
  B[r0 + y, c0 + x] = tile[x][x ^ y];
}

CUDA中的swizzling机制通过对共享内存中元素的位置进行重排，避免了多线程访问同一memory bank引起的数据冲突（bank conflict）。在传统的共享内存访问中，不同线程可能会访问相同的memory bank，导致访问冲突并降低性能。swizzling机制通过改变数据在共享内存中的物理布局，实现了每个线程访问不同的bank，从而减少了冲突。在swizzling机制中，逻辑坐标和物理坐标之间存在一一对应的映射关系，具体为：物理行`rp`与逻辑行`rl`一致，而物理列`cp`由逻辑行和逻辑列通过异或运算得出。通过这种映射，数据被均匀分布到不同的banks中，避免了数据重叠和冲突，从而提高了访问效率。以下是示例代码：
cpp
template
__global__ void transposeSharedSwizzling(float* A, float* B, const int M, const int N) {
  __shared__ float tile[Bm][Bn];

  int r0 = blockIdx.y * Bm;
  int c0 = blockIdx.x * Bn;
  int y = threadIdx.y;
  int x = threadIdx.x;

  // 读取阶段：数据重排以避免bank conflict
  tile[y][x ^ y] = A[r0 + y, c0 + x];

  __syncthreads();

  // 写入阶段：将数据存回全局内存
  B[r0 + y, c0 + x] = tile[x][x ^ y];
}

在CUDA程序中，swizzling技术可以有效减少共享内存的bank conflict，从而提高矩阵转置操作的效率。具体来说，swizzling机制通过对共享内存中元素的列索引进行异或变换，使得矩阵元素在共享内存中的物理位置重新排列，确保每个线程访问不同的bank，从而减少了冲突。以矩阵转置为例，假设要将矩阵`A`转置为矩阵`B`，传统的做法可能会导致线程访问同一列的元素，从而引发bank conflict。通过swizzling，我们将列索引转换为`cp = cl ^ rl`，使得每个线程访问共享内存的不同列，从而避免了冲突。以下是一个矩阵转置的完整代码示例：
cpp
template
__global__ void transposeSharedSwizzling(float* A, float* B, const int M, const int N) {
  __shared__ float tile[Bm][Bn];

  // 计算矩阵A的起始坐标
  int r0 = blockIdx.y * Bm;
  int c0 = blockIdx.x * Bn;
  int y = threadIdx.y;
  int x = threadIdx.x;

  // 读取阶段：将数据从矩阵A加载到共享内存，使用swizzling避免bank conflict
  tile[y][x ^ y] = A[r0 + y, c0 + x];
  __syncthreads();

  // 写入阶段：将转置后的数据写回矩阵B
  B[c0 + y, r0 + x] = tile[x][x ^ y];
}

在CUDA中优化transpose算子时，最常用的方法是利用共享内存来减少对全局内存的访问。通过将输入矩阵按块划分并加载到共享内存中，可以显著提高内存访问效率，尤其是在矩阵维度较大的情况下。具体实现时，可以采用tiling技术，将矩阵分为多个较小的子矩阵（tile）。例如，使用32x32的线程块，并在共享内存中存储每个子矩阵。当线程块中的线程完成对局部矩阵的转置操作后，再将其写回全局内存。下面是一个CUDA代码示例：
cpp
#define TILE_WIDTH 32
__global__ void transpose(float *odata, const float *idata, int width) {
    __shared__ float tile[TILE_WIDTH][TILE_WIDTH + 1];
    int x = blockIdx.x * TILE_WIDTH + threadIdx.x;
    int y = blockIdx.y * TILE_WIDTH + threadIdx.y;
    if (x < width && y < width) {
        tile[threadIdx.y][threadIdx.x] = idata[y * width + x];
    }
    __syncthreads();
    x = blockIdx.y * TILE_WIDTH + threadIdx.x;
    y = blockIdx.x * TILE_WIDTH + threadIdx.y;
    if (x < width && y < width) {
        odata[y * width + x] = tile[threadIdx.y][threadIdx.x];
    }
}

该代码通过使用共享内存来减少全局内存访问，从而提高性能，尤其是在较大矩阵的转置操作中。

要在 Hopper 架构上隐藏 wgmma 指令由 Shared Memory 供数引起的 18 个及以上周期延迟，核心思想是提前将 A/B 矩阵分块加载到 Shared Memory，并通过异步拷贝与 Tensor Core 计算形成深流水，使 Tensor Pipe 始终处于饱和状态。下面给出一个简化但结构正确的 CUDA 示例，展示如何组织 Shared Memory、cp.async 以及 wgmma 风格的计算调度思路，虽然代码中无法直接内联 wgmma 指令，但其结构与真实 Hopper Tensor Core kernel 一致。

cuda
#include 
#include 

#define M 64
#define N 16
#define K 16

extern "C" __global__ void hopper_tc_gemm(const half* A, const half* B, float* C) {
    __shared__ half As[M * K];
    __shared__ half Bs[N * K];

    int tid = threadIdx.x;

    // 预取 A
    for (int i = tid; i < M * K; i += blockDim.x) {
        As[i] = A[i];
    }
    // 预取 B
    for (int i = tid; i < N * K; i += blockDim.x) {
        Bs[i] = B[i];
    }
    __syncthreads();

    // 模拟 Tensor Core 计算
    float acc = 0.0f;
    int row = tid % M;
    if (row < M) {
        for (int k = 0; k < K; ++k) {
            acc += __half2float(As[row * K + k]) * __half2float(Bs[(tid / M) * K + k]);
        }
        C[row] = acc;
    }
}


在真实的 Hopper 优化版本中，这里的 Shared Memory 加载会被 cp.async.bulk 指令替代，并在多个 stage 中滚动缓冲，wgmma.mma_async 指令则由一个 warp-group 反复发射，从而在 A/B 数据仍在加载下一个 tile 时，前一个 tile 的 Tensor Core 计算已经在 Tensor Pipe 中执行。只要加载带宽和指令发射能够持续填满流水，18 个周期甚至更高的单指令延迟都会被完全隐藏，这也是成熟算子在 H100/H800 上能接近理论 FLOPs/TCU/cycle 的根本原因。

高效CUDA内核设计的核心在于缩小计算单元与HBM带宽之间的巨大鸿沟，这需要最大化数据复用并保证良好的访存模式。GPU存储层次从HBM到寄存器逐级变快，任何一次不必要的全局内存访问都会极大拉低性能，因此典型做法是通过tile化将全局数据分块加载到共享内存中复用。共享内存的访问同样需要遵循warp内32个线程访问连续、对齐、步幅为1的原则，否则会引发bank conflict。下面给出一个简化的矩阵乘法kernel示例，展示如何使用共享内存tile化计算并满足这些规则。

cuda
#include 

#define TILE 16

__global__ void matmul_tiled(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    int row = blockIdx.y * TILE + threadIdx.y;
    int col = blockIdx.x * TILE + threadIdx.x;

    float acc = 0.0f;

    for (int t = 0; t < (N + TILE - 1) / TILE; ++t) {
        int a_col = t * TILE + threadIdx.x;
        int b_row = t * TILE + threadIdx.y;

        if (row < N && a_col < N)
            As[threadIdx.y][threadIdx.x] = A[row * N + a_col];
        else
            As[threadIdx.y][threadIdx.x] = 0.0f;

        if (b_row < N && col < N)
            Bs[threadIdx.y][threadIdx.x] = B[b_row * N + col];
        else
            Bs[threadIdx.y][threadIdx.x] = 0.0f;

        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}


在这个kernel中，每个block包含16×16个线程，对应一个tile。warp内线程在加载A和B时访问的是连续的全局内存地址，保证了全局内存的coalescing；加载到共享内存后，每个元素会被tile内多个线程重复使用，从而显著降低HBM带宽需求。共享内存数组的布局也确保warp内线程访问连续地址，避免bank conflict。这样的设计在保证不发生寄存器或共享内存溢出的前提下，通常可以获得良好的性能，即使Occupancy不是理论最大值，也能实现更高的实际吞吐。

在CUDA中，通过使用多个流（streams）和异步数据拷贝，可以将主机到设备（H2D）或设备到主机（D2H）的数据传输与内核计算进行重叠，从而提升程序的整体性能。具体实现方法是使用 `cudaMemcpyAsync` 函数进行异步数据传输，同时利用多个流来实现数据传输与内核执行的并行。为了避免阻塞主机，通常还会使用pinned memory来提高数据传输效率。代码示例：
cpp
cudaStream_t stream1, stream2;
cudaStreamCreate(&stream1);
cudaStreamCreate(&stream2);

// 异步数据传输
cudaMemcpyAsync(d_data1, h_data1, size, cudaMemcpyHostToDevice, stream1);
cudaMemcpyAsync(d_data2, h_data2, size, cudaMemcpyHostToDevice, stream2);

// 在不同流中执行两个内核
kernel>>(d_data1);
kernel>>(d_data2);

// 等待流完成
cudaStreamSynchronize(stream1);
cudaStreamSynchronize(stream2);

通过这种方式，数据传输和计算可以并行进行，从而显著提升性能。

Tensor Core是NVIDIA的专用硬件单元，设计用来加速深度学习中的矩阵乘法计算。在CUDA中，如果要充分利用Tensor Core，需要确保矩阵运算符合Tensor Core的要求。例如，在Volta、Turing和Ampere架构中，Tensor Core主要用于矩阵乘法运算，尤其是浮动点16位（FP16）和浮动点32位（FP32）数据类型的运算。为了启用Tensor Core，首先要确保使用的矩阵大小适配Tensor Core的要求，通常是8x8的块大小；其次，可以使用`cutlass`库或直接通过CUDA内置的`cublas`库来调用Tensor Core。例如，`cublasGemmEx`函数可以利用Tensor Core来加速矩阵乘法计算。代码示例：
cpp
cublasHandle_t handle;
cublasCreate(&handle);

// 设置矩阵维度和数据类型
int m = 1024, n = 1024, k = 1024;
float *A, *B, *C;

// 分配内存
cudaMalloc(&A, m*k * sizeof(float));
cudaMalloc(&B, k*n * sizeof(float));
cudaMalloc(&C, m*n * sizeof(float));

// 使用Tensor Core进行矩阵乘法
float alpha = 1.0, beta = 0.0;
cublasGemmEx(handle, CUBLAS_OP_N, CUBLAS_OP_N, m, n, k, &alpha, A, CUDA_R_32F, m, B, CUDA_R_32F, k, &beta, C, CUDA_R_32F, m, CUBLAS_GEMM_DEFAULT);

// 清理资源
cudaFree(A); cudaFree(B); cudaFree(C);
cublasDestroy(handle);

通过这种方式，矩阵运算不仅得到了加速，而且利用了Tensor Core的并行计算能力，提升了性能。

在CUDA中实现扫描算法可以通过多个阶段的GPU核函数来完成。首先，我们使用`ScanAndWritePartSumKernel`核函数来计算每个块的部分和，并将结果存储在`part`数组中。每个线程通过循环处理属于自己部分的输入数据，并累加计算结果。对于每个块的第一个线程，累加结果会被存储到`output`数组中。`part`数组保存每个块的和。然后，我们使用`ScanPartSumKernel`核函数进一步对`part`数组进行前缀和操作，计算出每个块的部分和的累积。最后，`AddBaseSumKernel`核函数将每个块之前的部分和加到当前块的输出数组中，从而完成最终的前缀和。以下是核函数代码示例：

cpp
__global__ void ScanAndWritePartSumKernel(const int32_t* input, int32_t* part, int32_t* output, size_t n, size_t part_num) {
  for (size_t part_i = blockIdx.x; part_i < part_num; part_i += gridDim.x) {
    size_t part_begin = part_i * blockDim.x;
    size_t part_end = min((part_i + 1) * blockDim.x, n);
    if (threadIdx.x == 0) {
      int32_t acc = 0;
      for (size_t i = part_begin; i < part_end; ++i) {
        acc += input[i];
        output[i] = acc;
      }
      part[part_i] = acc;
    }
  }
}

__global__ void ScanPartSumKernel(int32_t* part, size_t part_num) {
  int32_t acc = 0;
  for (size_t i = 0; i < part_num; ++i) {
    acc += part[i];
    part[i] = acc;
  }
}

__global__ void AddBaseSumKernel(int32_t* part, int32_t* output, size_t n, size_t part_num) {
  for (size_t part_i = blockIdx.x; part_i < part_num; part_i += gridDim.x) {
    if (part_i == 0) {
      continue;
    }
    int32_t index = part_i * blockDim.x + threadIdx.x;
    if (index < n) {
      output[index] += part[part_i - 1];
    }
  }
}

为了在每个线程块内加速扫描操作，可以通过利用共享内存减少对全局内存的访问，从而提高计算效率。在扫描算法中，特别是在`ScanAndWritePartSumKernel`核函数中，输入数据在每个线程块内被加载到共享内存中进行处理。每个线程块内的线程计算其对应数据的前缀和，并将结果存储到共享内存中。对于块内的扫描操作，可以采用类似‘扫描-交换’的方式，在共享内存中逐步计算结果。通过使用共享内存，线程可以共享其局部计算结果，从而减少全局内存的访问次数，提升性能。以下是具体代码示例：

cpp
__global__ void ScanAndWritePartSumKernel(const int32_t* input, int32_t* part, int32_t* output, size_t n, size_t part_num) {
  extern __shared__ int32_t shared_mem[];
  for (size_t part_i = blockIdx.x; part_i < part_num; part_i += gridDim.x) {
    size_t part_begin = part_i * blockDim.x;
    size_t part_end = min((part_i + 1) * blockDim.x, n);
    for (size_t i = part_begin + threadIdx.x; i < part_end; i += blockDim.x) {
      shared_mem[threadIdx.x] = input[i];
      __syncthreads();
      int32_t acc = 0;
      for (size_t j = 0; j <= threadIdx.x; ++j) {
        acc += shared_mem[j];
      }
      output[i] = acc;
      __syncthreads();
    }
  }
}

在进行大规模数据前缀和计算时，性能优化通常通过分阶段策略来实现。首先，通过将输入数据分成多个部分，每个部分由独立线程块处理，使用`ScanAndWritePartSumKernel`进行局部前缀和的计算。在这个阶段，确保每个线程块的计算局部数据时，充分利用共享内存以减少全局内存访问。这可以显著提高计算速度。接着，使用`ScanPartSumKernel`对每个线程块的部分和进行前缀和计算，进一步累积每块的结果。最后，使用`AddBaseSumKernel`将每个部分和的结果加到全局输出中，这样就能得到最终的前缀和结果。分阶段处理使得每个阶段的内存访问和计算复杂度都较低，有助于在不同规模的数据上实现更高的并行效率。为了优化性能，需要注意以下几点：
1. 线程块的划分要合理，确保每个线程块处理的任务大小合适，避免内存访问冲突。
2. 共享内存的使用要尽量高效，减少无谓的同步和内存拷贝。
3. 在不同阶段之间的同步要小心管理，避免不必要的等待时间。通过这些优化，能够充分利用GPU的并行计算能力，显著提升大规模数据前缀和计算的效率。

cpp
__global__ void ScanAndWritePartSumKernel(const int32_t* input, int32_t* part, int32_t* output, size_t n, size_t part_num) {
  for (size_t part_i = blockIdx.x; part_i < part_num; part_i += gridDim.x) {
    size_t part_begin = part_i * blockDim.x;
    size_t part_end = min((part_i + 1) * blockDim.x, n);
    if (threadIdx.x == 0) {
      int32_t acc = 0;
      for (size_t i = part_begin; i < part_end; ++i) {
        acc += input[i];
        output[i] = acc;
      }
      part[part_i] = acc;
    }
  }
}

__global__ void ScanPartSumKernel(int32_t* part, size_t part_num) {
  int32_t acc = 0;
  for (size_t i = 0; i < part_num; ++i) {
    acc += part[i];
    part[i] = acc;
  }
}

__global__ void AddBaseSumKernel(int32_t* part, int32_t* output, size_t n, size_t part_num) {
  for (size_t part_i = blockIdx.x; part_i < part_num; part_i += gridDim.x) {
    if (part_i == 0) {
      continue;
    }
    int32_t index = part_i * blockDim.x + threadIdx.x;
    if (index < n) {
      output[index] += part[part_i - 1];
    }
  }
}

消除warp级Scan中的if判断，本质是为了避免由于lane条件不同导致的控制流分歧，从而让warp内32个线程执行完全一致的指令流。问题在于，原本不满足条件的线程会访问负偏移地址，从而产生越界访问。Zero Padding的思路是在共享内存中为每个warp预留额外的padding空间，使得这些负偏移访问实际上落在合法且值为0的内存区域中，这样即使所有线程无条件执行累加操作，计算结果依然正确。实现时通常会在共享内存中为每个warp分配一个长度为32加上最大偏移量的数组，并让warp的起始指针向后偏移padding大小。这样lane较小的线程在访问-shift位置时，只会读到0，不影响前缀和结果。下面给出一个完整且语法正确的CUDA示例代码，展示了无分支warp级Scan的实现方式。

__device__ __forceinline__ void ScanWarpNoIf(int32_t* shm_base) {
  int lane = threadIdx.x & 31;
  volatile int32_t* v = shm_base;
  v[0] += v[-1];
  __syncwarp();
  v[0] += v[-2];
  __syncwarp();
  v[0] += v[-4];
  __syncwarp();
  v[0] += v[-8];
  __syncwarp();
  v[0] += v[-16];
  __syncwarp();
}

__global__ void ScanKernel(int32_t* data, int n) {
  extern __shared__ int32_t shm[];
  int tid = threadIdx.x + blockIdx.x * blockDim.x;
  int warp_id = threadIdx.x >> 5;
  int lane = threadIdx.x & 31;
  const int PAD = 16;
  int32_t* warp_shm = shm + warp_id * (32 + PAD) + PAD;
  if (tid < n) {
    warp_shm[lane] = data[tid];
  } else {
    warp_shm[lane] = 0;
  }
  __syncwarp();
  ScanWarpNoIf(warp_shm + lane);
  __syncwarp();
  if (tid < n) {
    data[tid] = warp_shm[lane];
  }
}

在这个实现中，通过为每个warp分配额外的16个padding元素，所有lane在执行v[-1]、v[-2]等操作时都不会发生越界访问，从而彻底移除了条件判断。这种方式在实际工程中常用于高性能Scan、Reduce以及更复杂的块级前缀和算子中，是CUDA性能优化中非常实用的一种技巧。

在CUDA中直接用单个kernel完成大规模一维前缀和在理论上不可行，核心原因是线程块之间缺乏全局同步机制，无法保证不同block之间的累加顺序正确，因此必须将问题拆解。常见做法是先在每个block内部完成局部scan，并将每个block的最终累加值写入一个part数组，然后对part数组做一次全局scan，最后再把前面block的累加结果加回到后续block的输出中。这种设计严格遵循CUDA的执行与同步模型，在保证正确性的前提下最大化并行度。下面是一个简化但完整的CUDA实现示例，展示了block内scan、分段和计算以及最终回填的基本结构：

