    __syncthreads();
    ptr[tid] += val;
    __syncthreads();
  }
}

__global__ void ScanKernel(const int32_t* input, int32_t* part,
                           int32_t* output, size_t n) {
  extern __shared__ int32_t shm[];
  size_t part_i = blockIdx.x;
  size_t index = part_i * blockDim.x + threadIdx.x;
  shm[threadIdx.x] = index < n ? input[index] : 0;
  __syncthreads();
  ScanBlock(shm);
  __syncthreads();
  if (index < n) output[index] = shm[threadIdx.x];
  if (threadIdx.x == blockDim.x - 1) part[part_i] = shm[threadIdx.x];
}

__global__ void AddBaseSumKernel(const int32_t* part, int32_t* output, size_t n) {
  size_t part_i = blockIdx.x;
  if (part_i == 0) return;
  size_t index = part_i * blockDim.x + threadIdx.x;
  if (index < n) output[index] += part[part_i - 1];
}

该结构在工业级scan算子中非常常见，也是理解后续CUB、Thrust等库实现的基础。

在block级scan实现中预留warp级缓冲区的核心目的是降低同步开销并支持分层scan结构。warp内部的32个线程在硬件层面天然同步，因此可以先在warp内完成一次快速scan，再由warp leader将结果写入共享内存的固定位置，随后由一个warp对这些warp和进行二次scan。这种分级结构可以显著减少__syncthreads的使用次数，同时避免bank conflict和不必要的全block通信。在你给出的实现中，shared memory前32个元素专门用于存储warp级部分和，后续线程实际数据从偏移32的位置开始，这样可以保证warp scan和block scan逻辑解耦且内存布局清晰。下面是一个体现该思想的完整CUDA示例：

__global__ void BlockScanWithWarpBuffer(const int32_t* input, int32_t* output, size_t n) {
  extern __shared__ int32_t shm[];
  int tid = threadIdx.x;
  int gid = blockIdx.x * blockDim.x + tid;

  int32_t val = gid = offset) val += v;
  }

  if (lane == 31) shm[tid >> 5] = val;
  __syncthreads();

  // first warp scans warp sums
  if (tid = offset) w += v;
