在CUDA编程中，优化线程块的占用率和共享内存使用需要根据具体的硬件资源限制进行设计。线程块的占用率指的是每个流式多处理器（SM）上可并发执行的线程块数量，受到寄存器数量、共享内存大小等资源的限制。为了优化占用率，首先要确定合适的线程块大小，使其能够高效地利用GPU的资源。一般来说，线程块的大小应该是32的倍数，因为GPU中的线程是按warp（32个线程）为单位进行调度的。此外，共享内存的使用也需要谨慎，确保每个线程块的共享内存需求不会超出SM的限制。过多的共享内存会降低可并发执行的线程块数量，从而影响性能。一个常见的优化策略是，通过tiling技术将大矩阵分割成适合GPU缓存的块，确保每个块能够充分利用共享内存，减少对全局内存的访问。以下是一个CUDA代码示例，展示如何配置线程块和共享内存以优化矩阵乘法性能：

cpp
#define TILE_WIDTH 16

__global__ void matrixMulSharedMem(float *A, float *B, float *C, int N) {
    __shared__ float A_shared[TILE_WIDTH][TILE_WIDTH];
    __shared__ float B_shared[TILE_WIDTH][TILE_WIDTH];
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int Row = blockIdx.y * TILE_WIDTH + ty;
    int Col = blockIdx.x * TILE_WIDTH + tx;

    float Cvalue = 0.0f;

    for (int ph = 0; ph < (N / TILE_WIDTH); ++ph) {
        A_shared[ty][tx] = A[Row * N + ph * TILE_WIDTH + tx];
        B_shared[ty][tx] = B[(ph * TILE_WIDTH + ty) * N + Col];
        __syncthreads();

        for (int k = 0; k < TILE_WIDTH; ++k) {
            Cvalue += A_shared[ty][k] * B_shared[k][tx];
        }
        __syncthreads();
    }

    if (Row < N && Col < N) {
        C[Row * N + Col] = Cvalue;
    }
}

CUDA中，利用共享内存可以显著减少全局内存访问，从而提高性能。具体的做法是通过将数据从全局内存加载到共享内存中，这样多个线程可以共享这些数据，避免每个线程都重复访问全局内存。例如，在矩阵乘法中，可以通过将输入矩阵划分为小块（tile），并将这些小块加载到共享内存中，多个线程同时从共享内存中读取数据，从而减少全局内存带宽的压力。以下是一个简单的矩阵乘法的CUDA代码示例：

cpp
__global__ void matrixMultiply(float *A, float *B, float *C, int N) {
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];
    int tx = threadIdx.x, ty = threadIdx.y;
    int Row = blockIdx.y * BLOCK_SIZE + ty;
    int Col = blockIdx.x * BLOCK_SIZE + tx;

    float Cvalue = 0;
    for (int ph = 0; ph < N / BLOCK_SIZE; ++ph) {
        As[ty][tx] = A[Row * N + ph * BLOCK_SIZE + tx];
        Bs[ty][tx] = B[(ph * BLOCK_SIZE + ty) * N + Col];
        __syncthreads();

        for (int k = 0; k < BLOCK_SIZE; ++k) {
            Cvalue += As[ty][k] * Bs[k][tx];
        }
        __syncthreads();
    }
    C[Row * N + Col] = Cvalue;
}

在这段代码中，矩阵A和B被分成小块，加载到共享内存As和Bs中，在每个block内进行矩阵乘法运算。这样，线程可以反复访问共享内存中的数据，而不必频繁地访问全局内存。

在CUDA编程中，优化内存访问模式以提高L1和L2缓存的命中率，可以显著提升性能。首先，要利用共享内存（`__shared__`）作为中间缓存存储经常访问的数据，减少对全局内存的访问。通过Tile技术，将数据划分为多个子块，使每个线程块都能重复访问共享内存中的数据，从而减少对全局内存的请求。具体来说，可以通过将矩阵乘法中的子矩阵加载到共享内存中，然后进行计算，减少对全局内存的重复访问。对于纹理内存，可以利用L1缓存的优化策略，通过纹理访问模式来确保相邻的数据在内存中是连续存储的，从而提升缓存命中率。以下是一个简单的CUDA代码示例，演示如何通过共享内存优化矩阵乘法：

cpp
#define TILE_WIDTH 16
__global__ void matrixMultiply(float *A, float *B, float *C, int Width) {
    __shared__ float shared_A[TILE_WIDTH][TILE_WIDTH];
    __shared__ float shared_B[TILE_WIDTH][TILE_WIDTH];
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int Row = blockIdx.y * TILE_WIDTH + ty;
    int Col = blockIdx.x * TILE_WIDTH + tx;

    float C_value = 0.0;
    for (int i = 0; i < Width / TILE_WIDTH; i++) {
        shared_A[ty][tx] = A[Row * Width + i * TILE_WIDTH + tx];
        shared_B[ty][tx] = B[(i * TILE_WIDTH + ty) * Width + Col];
        __syncthreads();
        for (int k = 0; k < TILE_WIDTH; k++) {
            C_value += shared_A[ty][k] * shared_B[k][tx];
        }
        __syncthreads();
    }
    C[Row * Width + Col] = C_value;
}

在CUDA编程中，优化GPU性能的一种方法是减少不必要的全局内存访问，从而避免浪费峰值持续速率。可以通过共享内存来加速数据访问，利用共享内存减少对全局内存的依赖。例如，使用Tile技术将数据划分为多个小块（Tile），通过线程块共享数据而非频繁访问全局内存。在矩阵乘法中，多个线程会合作加载数据到共享内存，并且每个线程只需访问一次全局内存，这样可以大幅提高内存带宽的利用率，并减少峰值持续速率的浪费。代码示例如下：
cpp
#define TILE_WIDTH 16
__global__ void matrixMultiply(float* A, float* B, float* C, int width) {
    __shared__ float shared_A[TILE_WIDTH][TILE_WIDTH];
    __shared__ float shared_B[TILE_WIDTH][TILE_WIDTH];
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = blockIdx.y * TILE_WIDTH + ty;
    int col = blockIdx.x * TILE_WIDTH + tx;
    float Cvalue = 0;
    for (int ph = 0; ph < width / TILE_WIDTH; ++ph) {
        shared_A[ty][tx] = A[row * width + ph * TILE_WIDTH + tx];
        shared_B[ty][tx] = B[(ph * TILE_WIDTH + ty) * width + col];
        __syncthreads();
        for (int k = 0; k < TILE_WIDTH; ++k) {
            Cvalue += shared_A[ty][k] * shared_B[k][tx];
        }
        __syncthreads();
    }
    C[row * width + col] = Cvalue;
}

高效的CUDA矩阵乘法通常通过tiling思想将计算分解为CTA级别的子问题，每个CTA负责计算结果矩阵中的一个tile，并通过LSU将所需的输入子矩阵从全局内存加载到共享内存。这样全局内存访问会先经过L1/L2缓存体系，若数据未命中再访问DRAM，而一旦加载到共享内存后，后续FMA计算全部使用片上存储完成，大幅降低访存延迟。LSU负责发出全局和共享内存的load/store指令，SM子分区调度warp在FMA管道上执行乘加运算。下面给出一个典型的CUDA矩阵乘法kernel示例，展示如何利用共享内存进行数据复用：

cuda
#define TILE 16
__global__ void matmul(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];
    int row = blockIdx.y * TILE + threadIdx.y;
    int col = blockIdx.x * TILE + threadIdx.x;
    float acc = 0.0f;
    for (int t = 0; t < N / TILE; ++t) {
        As[threadIdx.y][threadIdx.x] = A[row * N + t * TILE + threadIdx.x];
        Bs[threadIdx.y][threadIdx.x] = B[(t * TILE + threadIdx.y) * N + col];
        __syncthreads();
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }
        __syncthreads();
    }
    C[row * N + col] = acc;
}

在这个实现中，每个CTA加载A和B的子块到共享内存，所有warp在共享内存上反复执行FMA运算，从而最大化算术强度并充分利用SM内的FMA管道和L2缓存体系，这也是实际高性能CUDA算子开发中的核心思路。

这两类停滞共同指向一个核心问题，即warp在等待内存相关数据返回，其中IMC miss说明常量缓存命中率低，而long scoreboard说明存在对L1TEX相关内存访问的长延迟依赖。GPU的常量内存设计初衷是让warp内线程以广播方式高效读取相同地址的数据，一旦warp内访问地址分散，就会退化为串行访问并放大延迟；而共享内存则提供了显式可控的低延迟数据复用机制。因此优化原则是将warp内高度一致、只读且反复使用的数据放入常量内存，而对访问模式复杂、需要多次重用的数据，显式加载到共享内存以打破对全局内存和L1TEX的长依赖链。下面的示例展示了将查找表放入常量内存，并将输入数据块加载到共享内存以减少scoreboard等待的典型写法。

#include 
#include 

__constant__ float c_lut[256];

__global__ void optimizedKernel(const float* __restrict__ input, float* output, int n) {
    __shared__ float tile[256];
    int tid = threadIdx.x;
    int gid = blockIdx.x * blockDim.x + tid;
    if (gid < n) {
        tile[tid] = input[gid];
    }
    __syncthreads();
    if (gid < n) {
        int idx = tid & 255;
        float v = tile[tid];
        float w = c_lut[idx];
        output[gid] = v * w;
    }
}

在这个实现中，常量数组 c_lut 被warp内线程以高度一致的方式访问，几乎等价于寄存器延迟，而输入数据先进入共享内存，避免了多次全局加载导致的L1TEX依赖和long scoreboard停滞，从而显著改善整体发射效率。

当分析结果显示内核已高度优化但仍由指令延迟主导时，核心思路是利用更多可调度的 warp 来覆盖这些延迟，使得当一个 warp 因为内存或算术指令等待时，调度器可以切换到其他就绪 warp 执行。通过 tiling 技术将全局内存访问转化为共享内存访问，可以显著降低 memory_l2_theoretical_sectors_global 以及 memory_l1_tag_requests_global 等指标，同时提高每条指令的数据复用率。循环展开可以减少分支和索引计算指令数量，降低 inst_executed 中的控制开销占比，并且有助于编译器生成更多独立指令，从而提升指令级并行度。下面是一个使用共享内存 tiling 的简化 CUDA 矩阵乘法示例：

#include 
#define TILE 16

__global__ void matmul_tiled(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];
    int row = blockIdx.y * TILE + threadIdx.y;
    int col = blockIdx.x * TILE + threadIdx.x;
    float acc = 0.0f;
    for (int k = 0; k < N; k += TILE) {
        As[threadIdx.y][threadIdx.x] = A[row * N + k + threadIdx.x];
        Bs[threadIdx.y][threadIdx.x] = B[(k + threadIdx.y) * N + col];
        __syncthreads();
        #pragma unroll
        for (int i = 0; i < TILE; ++i) {
            acc += As[threadIdx.y][i] * Bs[i][threadIdx.x];
        }
        __syncthreads();
    }
    C[row * N + col] = acc;
}

在该实现中，每个 block 内有足够多的线程形成多个活动 warp，有助于提升占用率并隐藏算术与内存指令的延迟；共享内存访问如果布局合理，可以使 derived__memory_l1_conflicts_shared_nway 接近 1；循环展开减少了循环控制指令数量，使得 inst_executed 中更多比例是有用的 FMA 指令，从而整体提升吞吐率。

在真实应用中，内核往往并不是在缓存完全为空的情况下运行的，而是继承了之前内核或数据加载阶段留下的缓存状态，因此直接分析“冷缓存”下的性能会与实际偏差较大。实践中通常通过显式的预热阶段来构造稳定的缓存状态，即在正式测量前运行一次或多次功能等价但不计时的内核，使L2甚至部分L1缓存中已经包含关键数据。这样在后续内核执行时，全局内存访问会更贴近真实负载。下面的CUDA示例展示了一个简单的缓存预热与测量分离的做法：首先执行warmupKernel访问目标数据，然后执行measureKernel进行真正的性能测量。这样即使分析工具默认刷新缓存，也可以在应用级别重建可控的缓存行为。

#include 
#include 

__global__ void warmupKernel(const float* data, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >>(d_in, n);
    cudaDeviceSynchronize();
    measureKernel>>(d_in, d_out, n);
    cudaDeviceSynchronize();
    cudaFree(d_in);
    cudaFree(d_out);
    return 0;
}

这种方式的核心思想是让分析关注点从工具层面的缓存控制转移到应用自身的执行语义上，从而得到更有工程价值的性能结论。

GPU持久化模式的本质是避免在每次CUDA程序启动和退出时反复进行GPU的初始化与反初始化，因为这些操作由内核模式驱动完成，开销虽短但并不稳定。当未启用持久化模式时，第一个触发GPU使用的进程会承担初始化成本，而最后一个退出的进程会触发关闭流程，这会直接污染内核启动时间、首个CUDA API调用延迟以及性能分析中的时间指标。启用持久化模式后，驱动会在系统层面保持GPU处于已初始化状态，从而使多次运行同一CUDA程序时的行为更加确定。下面的代码示例展示了一个对启动延迟敏感的微基准测试，通过多次重复启动内核可以明显观察到持久化模式对一致性的改善。

#include 
#include 

__global__ void emptyKernel() {}

int main() {
    const int iters = 1000;
    cudaEvent_t start, stop;
    cudaEventCreate(&start);
    cudaEventCreate(&stop);
    cudaEventRecord(start);
    for (int i = 0; i >>();
    }
    cudaEventRecord(stop);
    cudaEventSynchronize(stop);
    float ms = 0.0f;
    cudaEventElapsedTime(&ms, start, stop);
    printf("Average launch time: %f us\n", ms * 1000.0f / iters);
    cudaEventDestroy(start);
    cudaEventDestroy(stop);
    return 0;
}

在启用持久化模式的系统上，多次运行该程序时平均内核启动时间会更加稳定，这对于使用Nsight Compute等工具进行对比分析尤为重要，因为它减少了与实际计算无关的系统噪声。

MIG将一块物理GPU拆分为多个逻辑CUDA设备，但这些设备在资源独占性上并不完全相同。隔离计算实例拥有完整且独占的SM集合，其行为等价于一块缩小规格的独立GPU，因此可以正常采集SM、L1、L2等硬件性能计数器。共享计算实例则与同一GPU实例中的其他计算实例共享部分GPU单元和内存带宽，这种共享破坏了性能计数器的归因准确性，因此分析工具会禁止从共享单元读取指标，只允许访问实例独占的资源。开发者在代码层面可以通过CUDA运行时查询设备属性来判断自己是否运行在MIG环境以及设备的规模，从而决定是否适合进行低层次性能分析。下面的示例代码展示了如何检测MIG设备并输出其SM数量。

