#include 

int main() {
    int device = 0;
    cudaSetDevice(device);
    cudaDeviceProp prop;
    cudaGetDeviceProperties(&prop, device);
    printf("Device name: %s\n", prop.name);
    printf("MultiProcessor count: %d\n", prop.multiProcessorCount);
