下面给出一个完整且工程中常用的一维数组加法CUDA示例，其中线程块大小固定为128，数组长度N可以为任意值，包括不是128整数倍的情况。其核心思想是主机端对grid_size进行向上取整配置，设备端通过条件判断过滤多余线程，从而保证计算正确性和内存安全。

cuda
#include 
#include 

__global__ void vecAdd(const float* x, const float* y, float* z, int N) {
    int n = blockDim.x * blockIdx.x + threadIdx.x;
    if (n >= N) return;
    z[n] = x[n] + y[n];
}

int main() {
    const int N = 100000001; // 不是128的整数倍
    const int block_size = 128;
    const int grid_size = (N + block_size - 1) / block_size;

    float *h_x, *h_y, *h_z;
    float *d_x, *d_y, *d_z;

    size_t bytes = N * sizeof(float);
    h_x = (float*)malloc(bytes);
    h_y = (float*)malloc(bytes);
    h_z = (float*)malloc(bytes);

    for (int i = 0; i >>(d_x, d_y, d_z, N);

    cudaMemcpy(h_z, d_z, bytes, cudaMemcpyDeviceToHost);

    printf("z[0]=%f, z[N-1]=%f\n", h_z[0], h_z[N-1]);

    cudaFree(d_x);
    cudaFree(d_y);
    cudaFree(d_z);
    free(h_x);
    free(h_y);
    free(h_z);
    return 0;
}


在这个示例中，即使N不是128的整数倍，grid_size的向上取整保证了最后一个元素一定有线程处理，而核函数中的if(n >= N) return则确保多余线程不会访问非法地址。这种写法在实际CUDA算子开发中几乎是标准模板，既安全又高效，也为后续引入设备函数、共享内存或更复杂的算子优化打下了稳定基础。

在CUDA中，设备函数可以像普通C++函数一样通过返回值、指针或引用返回结果，这三种方式在语义上完全等价，编译器生成的PTX和最终机器指令通常也不会有本质差别，性能上不会因为返回方式不同而产生可观差异。下面给出一个完整示例，展示三种设备函数的定义以及核函数中的调用方式：

#include 
#include 

__device__ float add_by_value(float a, float b) {
    return a + b;
}

__device__ void add_by_pointer(float a, float b, float* out) {
    *out = a + b;
}

__device__ void add_by_reference(float a, float b, float& out) {
    out = a + b;
}

__global__ void add_kernel(const float* x, const float* y, float* z, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >>(dx, dy, dz, n);
    cudaDeviceSynchronize();

    cudaFree(dx);
    cudaFree(dy);
    cudaFree(dz);
