    int n = blockIdx.x + threadIdx.x * gridDim.x;
    z[n] = x[n] + y[n];
}
add_stride>>(x, y, z);

该代码确保线程块中的每个线程访问的数据是连续的，从而减少内存访问的非合并性，提升了内存访问的效率。

