__global__ void transpose2(float *A, float *B, int N) {
  int nx = threadIdx.x + blockIdx.x * blockDim.x;
  int ny = threadIdx.y + blockIdx.y * blockDim.y;
  if(nx < N && ny < N) {
    B[nx * N + ny] = A[ny * N + nx];
  }
}

