    unsigned int tid = threadIdx.x;
    unsigned int base = blockIdx.x * blockDim.x;
    float* x = &d_x[base];

    for (unsigned int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride && base + tid + stride < N) {
            x[tid] += x[tid + stride];
        }
        __syncthreads();
    }
}

该核函数的核心思想是让每个线程块独立地对其负责的blockDim.x个元素进行归约。通过将指针x指向当前线程块在全局内存中的起始位置，可以在逻辑上把全局数组分割成若干连续的小段。每一轮循环中，stride表示当前折半的跨度，线程tid小于stride的线程负责从后半段读取一个元素并累加到前半段对应位置。由于这一过程存在明确的跨线程读写依赖，因此在每一轮累加之后必须调用__syncthreads，以确保所有线程都完成了本轮的写操作后，才进入下一轮归约。最终，当stride减小到1时，线程0中保存的值就是该线程块对应数据段的部分和。整个过程不依赖线程块之间的执行顺序，因此无需也无法进行跨线程块同步。

