通过使用CUDA流和异步数据传输（如cudaMemcpyAsync()），可以显著提高主机与设备之间的数据传输性能。在默认情况下，数据传输（H2D或D2H）是阻塞的，会等待完成后才能继续执行后续操作。为了打破这一限制，可以将数据传输放入不同的CUDA流中，从而与核函数的执行重叠。为了实现这一点，主机内存需要声明为不可分页内存（pinned memory）。这种内存具有固定的物理地址，可以在数据传输期间保持不变，避免了数据从可分页内存移动到不可分页内存的延迟。此外，使用异步传输时，主机可以在数据传输的同时进行其他计算，充分利用GPU的并行计算能力。以下是一个示例代码，展示如何使用cudaMemcpyAsync()和CUDA流来实现数据传输与核函数执行的重叠：

cpp
cudaStream_t stream1, stream2;
cudaStreamCreate(&stream1);
cudaStreamCreate(&stream2);

// 分配主机内存（不可分页内存）
float *h_data;
cudaMallocHost((void**)&h_data, size);

// 分配设备内存
data_type *d_data;
cudaMalloc((void**)&d_data, size);

// 在stream1中异步传输数据从主机到设备
cudaMemcpyAsync(d_data, h_data, size, cudaMemcpyHostToDevice, stream1);

// 在stream2中执行核函数
kernel>>(d_data);

// 在stream1中异步传输数据从设备到主机
cudaMemcpyAsync(h_data, d_data, size, cudaMemcpyDeviceToHost, stream1);

// 等待流完成
cudaStreamSynchronize(stream1);
cudaStreamSynchronize(stream2);

// 清理资源
cudaFreeHost(h_data);
cudaFree(d_data);
cudaStreamDestroy(stream1);
cudaStreamDestroy(stream2);

