#define TILE_WIDTH 16

__global__ void matrixTranspose(int *in, int *out, int width) {
    __shared__ int tile[TILE_WIDTH][TILE_WIDTH];
    int x = blockIdx.x * TILE_WIDTH + threadIdx.x;
    int y = blockIdx.y * TILE_WIDTH + threadIdx.y;

    if (x < width && y < width) {
        tile[threadIdx.y][threadIdx.x] = in[y * width + x];
    }

    __syncthreads();

    x = blockIdx.y * TILE_WIDTH + threadIdx.x;
    y = blockIdx.x * TILE_WIDTH + threadIdx.y;

    if (x < width && y < width) {
        out[y * width + x] = tile[threadIdx.y][threadIdx.x];
    }
}


在这段代码中，`tile` 是共享内存数组，线程块的大小为 `TILE_WIDTH x TILE_WIDTH`，每个线程通过共享内存加载数据，并在转置后将结果写回全局内存。通过合理的共享内存管理，可以避免全局内存的重复访问，从而提高效率。

在CUDA编程中，行主序和列主序的内存访问模式会对内存访问的效率产生重要影响。为了优化这些访问，首先需要考虑共享内存的布局和线程块的组织。共享内存的访问模式应该避免冲突，特别是在写入和读取时。通常，行主序访问和列主序访问的矩阵操作会引发存储体冲突（bank conflicts），因为多个线程同时访问共享内存的同一位置，导致性能下降。

在行主序和列主序优化中，一种常见的做法是使用“tiling”技术。将矩阵分割为小的块（tile），并且保证每个线程块在共享内存中处理一个块的子矩阵。特别是，如果在行主序下进行写入操作，线程块的最内层维度应该与共享内存数组的最内层维度匹配，以减少冲突。在列主序读取时，则可以通过调整线程块的布局，避免多个线程同时访问共享内存中的同一列。

以下是一个示例，展示了如何优化行主序写入和列主序读取：

cpp
#define BDIM_X 16
#define BDIM_Y 16

__global__ void transposeOptimized(int *in, int *out, int width) {
    __shared__ int tile[BDIM_Y][BDIM_X];
    int x = blockIdx.x * BDIM_X + threadIdx.x;
    int y = blockIdx.y * BDIM_Y + threadIdx.y;

    // 行主序写入共享内存
    if (x < width && y < width) {
        tile[threadIdx.y][threadIdx.x] = in[y * width + x];
    }

    __syncthreads();

    // 列主序读取共享内存并写入全局内存
    x = blockIdx.y * BDIM_X + threadIdx.x;
    y = blockIdx.x * BDIM_Y + threadIdx.y;

    if (x < width && y < width) {
        out[y * width + x] = tile[threadIdx.y][threadIdx.x];
    }
}


通过这种方式，避免了存储体冲突，优化了内存访问。共享内存中的数据按照矩阵块的大小进行组织，并通过合适的线程索引进行访问，从而保证了内存访问的合并性，进一步提高了性能。

