        shared_B[tx][ty] = B[(i * TILE_SIZE + ty) * num_cols + col];
        __syncthreads();
        // 计算tile内的部分结果
    }

4. 计算完成后，将结果存储到输出矩阵。通过Tiling技术，线程块能够高效地利用共享内存进行数据复用，显著提高计算速度和内存带宽利用率。

在CUDA编程中，利用共享内存进行矩阵乘法优化可以显著提升性能，减少对全局内存的访问。通常，矩阵被划分为多个子矩阵（tile），每个子矩阵会加载到共享内存中，线程块之间协作处理该子矩阵。由于共享内存比全局内存的访问延迟低且带宽高，线程可以频繁访问共享内存中的数据，而无需每次都从全局内存中加载。具体实现中，可以使用`__shared__`修饰符来定义共享内存数组，例如将输入矩阵的块加载到共享内存`Mds`和`Nds`。每个线程处理子矩阵的一个元素，示例代码如下：

cpp
__global__ void matmul_kernel(float *M, float *N, float *P, int Width) {
    __shared__ float Mds[TILE_WIDTH][TILE_WIDTH];
    __shared__ float Nds[TILE_WIDTH][TILE_WIDTH];
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int Row = blockIdx.y * TILE_WIDTH + ty;
    int Col = blockIdx.x * TILE_WIDTH + tx;

    float Pvalue = 0;
    for (int ph = 0; ph < Width / TILE_WIDTH; ++ph) {
        Mds[ty][tx] = M[Row * Width + ph * TILE_WIDTH + tx];
        Nds[ty][tx] = N[(ph * TILE_WIDTH + ty) * Width + Col];
        __syncthreads();
        for (int k = 0; k < TILE_WIDTH; ++k) {
            Pvalue += Mds[ty][k] * Nds[k][tx];
        }
        __syncthreads();
    }
    P[Row * Width + Col] = Pvalue;
}

为了减少不必要的全局内存访问，可以使用共享内存和tiling技术。具体来说，首先将输入矩阵分成多个子矩阵（Tile），并将每个子矩阵加载到共享内存中。共享内存具有更低的访问延迟和更高的带宽，能够大幅提高访问速度，减少对全局内存的频繁访问。在CUDA代码中，可以通过以下方式实现：

__shared__ float Mds[TILE_WIDTH][TILE_WIDTH];
Mds[ty][tx] = M[Row * Width + ph * TILE_WIDTH + tx];

在这个例子中，`Mds`是共享内存的一个二维数组，每个线程从全局内存中加载矩阵的一部分到共享内存中，并且这些线程共享数据，避免了重复的全局内存访问。通过这种方式，不仅能提高计算效率，还能减轻内存带宽的压力。

在TileLang中，收集用于缓冲区定义的变量时，应该使用`CollectVarsUsedInBufferDefinition`辅助函数，该函数会遍历所有`BufferLoad`和`BufferStore`节点，并收集其中使用的变量。具体实现方式如下：

cpp
void VisitBuffer(const Buffer &buf) {
    // 收集应该保留定义的变量
    VarUseDefAnalyzer usage(Array{});
    usage(buf->data);
    for (const auto &dim : buf->shape) {
        usage(dim);
    }
    for (const auto &dim : buf->strides) {
        usage(dim);
    }
    usage(buf->elem_offset);

    // 在LetStmtNode变异器中跟踪未定义变量
    for (const auto &var : usage.undefined_) {
        used_in_buffer_def_.insert(var.get());
    }
}


这个代码片段会检查`Buffer`对象中的`data`、`shape`、`strides`以及`elem_offset`等字段，确保在对`Buffer`进行内联优化时，不会错误地移除这些关键的变量。这样可以避免在后续代码中访问缓冲区时遇到无法找到这些变量的错误。
